// Obter dados de entrada
const cpf = $('Merge State').item.json.message_text;
const html = $input.first().json.data || '';

console.log('Processando CPF:', cpf);
console.log('HTML recebido:', html.length, 'caracteres');

// Obter data e hora atual
const agora = new Date();
const dataHora = agora.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

// CASO 1: Verificar se eh pagina de LISTA de processos
const hasProcessList = html.includes('Processos encontrados') || html.includes('linkProcesso');

// CASO 2: Verificar se eh pagina de DETALHE de processo unico
const isSingleProcessPage = html.includes('Tramitacao prioritaria') ||
                            (html.includes('Classe') && html.includes('Assunto') && html.includes('Foro') && html.includes('Vara'));

if (!hasProcessList && !isSingleProcessPage) {
  console.log('Nenhum processo encontrado');
  return [{
    json: {
      responseText: 'Consulta sistema do Tribunal Judiciario CPF: ' + cpf + ' - Nenhum processo encontrado, digite menu para voltar ao inicio',
      nome_extraido: 'N/A',
      processos_array: [],
      total_processos: 0
    }
  }];
}

console.log('Processos encontrados, extraindo dados...');

const processos = [];
let nome = 'N/A';

// Funcao para limpar nome extraido
function limparNome(texto) {
  if (!texto) return 'N/A';
  let limpo = texto.replace(/<[^>]+>/g, ' ');
  limpo = limpo.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&');
  limpo = limpo.split(/Advogado|<br/i)[0];
  limpo = limpo.replace(/[\\s\\n\\r]+/g, ' ').trim();
  if (/^\\d{2}\\/\\d{2}\\/\\d{4}/.test(limpo)) return 'N/A';
  if (limpo.length < 3) return 'N/A';
  return limpo;
}

// CASO 2: Processo unico - extrair da pagina de detalhes
if (isSingleProcessPage && !hasProcessList) {
  console.log('Processando pagina de processo unico...');

  const numeroRegex = /(\\d{7}-\\d{2}\\.\\d{4}\\.\\d\\.\\d{2}\\.\\d{4})/;
  const numeroMatch = html.match(numeroRegex);
  const numeroProcesso = numeroMatch ? numeroMatch[1] : '';

  // Extrair classe do processo (Precatório, Requisição de Pequeno Valor, etc)
  // Busca após "Classe" no HTML
  const classeMatch = html.match(/Classe[\s\S]*?<[^>]*>([^<]*(?:Precatório|Requisição de Pequeno Valor)[^<]*)/i);
  let classeProcesso = '';
  if (classeMatch) {
    classeProcesso = classeMatch[1].trim();
  } else {
    // Tentar outra abordagem - buscar diretamente
    if (html.includes('Precatório')) classeProcesso = 'Precatório';
    else if (html.includes('Requisição de Pequeno Valor')) classeProcesso = 'Requisição de Pequeno Valor';
  }

  // Extrair nome do requerente (Reqte)
  const nomeMatch = html.match(/Reqte[\s\S]*?<[^>]*>([^<]+)/);
  if (nomeMatch && nomeMatch[1]) {
    nome = nomeMatch[1].trim();
  }

  // Extrair data (usar data atual como fallback)
  const dataProcesso = dataHora.split(',')[0]; // Pega só a data

  if (numeroProcesso) {
    processos.push({
      numero: numeroProcesso,
      classe: classeProcesso || 'Processo',
      data: dataProcesso
    });
    console.log('✅ Processo único extraído:', numeroProcesso, '-', classeProcesso);
  }
} else {
  // CASO 1: Lista de processos - lógica original
  console.log('📋 Processando lista de processos...');

  // Extrair nome do requerente
  const nomeMatches = html.match(/<div class=\"unj-base-alt nomeParte\">\s*([^<]+)/);
  if (nomeMatches && nomeMatches[1]) {
    nome = nomeMatches[1].trim();
    console.log('👤 Nome encontrado:', nome);
  }

  // Buscar todas as seções de processo
  const processosMatches = html.match(/<li>\s*<div id=\"divProcesso[^\"]*\"[^>]*>.*?<\/div>\s*<\/li>/gs);

  if (processosMatches) {
    console.log('📋 Encontradas', processosMatches.length, 'seções de processo');

    processosMatches.forEach((processoHtml, index) => {
      const numeroMatch = processoHtml.match(/class=\"linkProcesso\"[^>]*>\s*([^<\s]+)/);
      const numeroProcesso = numeroMatch ? numeroMatch[1].trim() : '';

      const classeMatch = processoHtml.match(/<div class=\"classeProcesso\">([^<]+)<\/div>/);
      const classeProcesso = classeMatch ? classeMatch[1].trim() : '';

      const dataMatch = processoHtml.match(/<div class=\"dataLocalDistribuicaoProcesso\">([^<]+?)\s*-/);
      const dataProcesso = dataMatch ? dataMatch[1].trim() : '';

      if (numeroProcesso && classeProcesso && dataProcesso) {
        processos.push({
          numero: numeroProcesso,
          classe: classeProcesso,
          data: dataProcesso
        });
        console.log('✅ Processo extraído:', numeroProcesso, '-', classeProcesso, '-', dataProcesso);
      }
    });
  }
}

console.log('📊 Total de processos extraídos:', processos.length);

// Montar resposta
let response = `🔍 *Consulta sistema do Tribunal Judiciário*\n\nPrezado(a) ${nome}, CPF: ${cpf}\n\n📋 Localizamos os seguintes requerimentos:\n`;

for (const processo of processos) {
  response += `🔹 ${processo.data} ${processo.numero} ${processo.classe}\n`;
}

response += `\n🏛️ *Consulta oficial realizada no sistema do Tribunal de Justiça às ${dataHora}*`;

console.log('✅ Resposta montada:', response.length, 'caracteres');

return [{
  json: {
    responseText: response,
    nome_extraido: nome,
    processos_array: processos,
    total_processos: processos.length
  }
}];

// Generate 6-digit verification code
const code = Math.floor(100000 + Math.random() * 900000).toString();
const email = $('Merge State').item.json.message_text;
const from = $('Merge State').item.json.from;

console.log('Codigo gerado:', code);
console.log('Email:', email);

return [{
  json: {
    verification_code: code,
    email: email,
    from: from,
    code_generated_at: new Date().toISOString()
  }
}];

// Validate verification code
const inputCode = $('Merge State').item.json.message_text;
const storedCode = $('Merge State').item.json.stored_code;
const storedEmail = $('Merge State').item.json.stored_email;
const minutesSinceUpdate = $('Merge State').item.json.minutes_since_update || 0;

console.log('Codigo digitado:', inputCode);
console.log('Codigo armazenado:', storedCode);
console.log('Minutos desde update:', minutesSinceUpdate);

// Check if code expired (15 minutes)
const isExpired = minutesSinceUpdate > 15;

// Check if code matches
const isValid = inputCode === storedCode && !isExpired;

let response = '';
let newState = 'AWAITING_CODE';

if (isExpired) {
  response = '⏰ *Código expirou!*\n\nO código de verificação expirou. Por favor, digite seu email novamente para receber um novo código.';
  newState = 'AWAITING_EMAIL';
} else if (isValid) {
  response = '✅ *Email verificado com sucesso!*\n\n💳 Para receber o laudo completo com cálculo atualizado, efetue o pagamento de R$ 99,90.\n\n🔗 Link de pagamento: [Em breve]\n\nApós o pagamento, você receberá o laudo no email: ' + storedEmail;
  newState = 'AWAITING_PAYMENT';
} else {
  response = '❌ *Código incorreto!*\n\nO código digitado não confere. Por favor, verifique e digite novamente o código de 6 dígitos enviado para seu email.';
  newState = 'AWAITING_CODE';
}

return [{
  json: {
    route: 'CODE',
    response: response,
    new_state: newState,
    code_valid: isValid,
    code_expired: isExpired,
    stored_email: storedEmail
  }
}];
